"""Version ranges, as written in manifests and in index dependencies (docs/ranges.md)."""

import re

from pinset.errors import RangeError
from pinset.version import BUILD_RE, NUMBER, PRERELEASE_RE, Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
WILDCARDS = ("x", "X", "*")
NUMBER_RE = re.compile(NUMBER)
SPACES_RE = re.compile(r"[ \t]+")
START_CHARS = set("0123456789xX*")


class Range:
    def __init__(self, text, alternatives, exact):
        self.text = text
        # Each alternative: (primitive bounds, releases named by a prerelease comparator).
        self._alternatives = alternatives
        self._exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        return any(self._test_alt(prims, carry, version) for prims, carry in self._alternatives)

    @staticmethod
    def _test_alt(prims, carry, v):
        for kind, arg in prims:
            if kind == "ge":
                ok = v >= arg
            elif kind == "gt":
                ok = v > arg
            elif kind == "le":
                ok = v <= arg
            elif kind == "lt":
                ok = v < arg
            elif kind == "eq":
                ok = v == arg
            elif kind == "below":
                ok = v.release < arg
            else:
                ok = False
            if not ok:
                return False
        if v.is_prerelease() and v.release not in carry:
            return False
        return True

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/ranges.md, section 10)."""
        return self._exact

    def __str__(self):
        return self.text


def _bad_version(msg):
    return RangeError("bad-version", msg)


def _parse_partial(text):
    """Returns (parts, prerelease tuple, build) where parts are ints or None for wildcards."""
    body, plus, build = text.partition("+")
    head, dash, pre = body.partition("-")
    pieces = head.split(".")
    if len(pieces) > 3:
        raise _bad_version(f"too many parts in {text!r}")
    parts = []
    for piece in pieces:
        if piece in WILDCARDS:
            parts.append(None)
        elif NUMBER_RE.fullmatch(piece):
            parts.append(int(piece))
        else:
            raise _bad_version(f"bad part {piece!r} in {text!r}")
    seen_wild = False
    for part in parts:
        if part is None:
            seen_wild = True
        elif seen_wild:
            raise _bad_version(f"a number after a wildcard in {text!r}")
    if dash or plus:
        if len(parts) != 3 or seen_wild:
            raise _bad_version(f"prerelease or build on a partial version in {text!r}")
        if dash and not PRERELEASE_RE.fullmatch(pre):
            raise _bad_version(f"bad prerelease in {text!r}")
        if plus and not BUILD_RE.fullmatch(build):
            raise _bad_version(f"bad build in {text!r}")
    return parts, tuple(pre.split(".")) if dash else (), build


class _Partial:
    def __init__(self, text):
        self.parts, self.pre, _ = _parse_partial(text)
        self.parts += [None] * (3 - len(self.parts))
        self.given = sum(1 for p in self.parts if p is not None)

    @property
    def full(self):
        return self.given == 3

    def low(self):
        return tuple(p or 0 for p in self.parts)

    def version(self):
        return Version(*self.low(), self.pre)

    def next_block(self):
        """Release just after the block the partial names; None for a wildcard major."""
        a, b, _ = self.parts
        if a is None:
            return None
        if b is None:
            return (a + 1, 0, 0)
        return (a, b + 1, 0)


def _lower(p):
    return [("ge", p.version())]


def _comparator(op, p):
    """Returns the primitive bounds of one comparator."""
    if p.given == 0:
        return [("none", None)] if op in ("<", ">") else []
    if op in ("^", "~"):
        low = [("ge", p.version())]
        a, b, c = p.parts
        if op == "~" or a != 0 and a is not None:
            if op == "~" and b is not None:
                up = (a, b + 1, 0)
            elif op == "~":
                up = (a + 1, 0, 0)
            else:
                up = (a + 1, 0, 0)
        elif b is None:
            up = (1, 0, 0)
        elif b != 0:
            up = (0, b + 1, 0)
        elif c is None:
            up = (0, 1, 0)
        else:
            up = (0, 0, c + 1)
        return low + [("below", up)]
    if p.full:
        v = p.version()
        return [({"=": "eq", ">": "gt", ">=": "ge", "<": "lt", "<=": "le"}[op], v)]
    nxt = p.next_block()
    if op == "=":
        return [("ge", p.version()), ("below", nxt)]
    if op == ">":
        return [("ge", Version(*nxt))]
    if op == ">=":
        return [("ge", p.version())]
    if op == "<":
        return [("below", p.low())]
    return [("below", nxt)]


def _split_operator(token):
    for op in OPERATORS:
        if token.startswith(op):
            return op, token[len(op):]
    return "", token


def _shape_alternative(alt):
    """Steps 3 to 5: returns ('hyphen', lo, hi) or ('set', [(op, text)])."""
    tokens = SPACES_RE.split(alt.strip(" \t"))
