        return ("hyphen", tokens[0], tokens[2])
    out = []
    for token in tokens:
        op, rest = _split_operator(token)
        if not rest or rest[0] not in START_CHARS:
            raise RangeError("bad-range", f"cannot read {token!r}")
        out.append((op, rest))
    return ("set", out)


OPERATORS_FIRST = ("<", ">", "=", "^", "~")


def _build_alternative(shape):
    prims = []
    carry = set()
    if shape[0] == "hyphen":
        lo, hi = _Partial(shape[1]), _Partial(shape[2])
        for p in (lo, hi):
            if p.full and p.pre:
                carry.add(p.low())
        if lo.given:
            prims.append(("ge", lo.version()))
        if hi.given:
            if hi.full:
                prims.append(("le", hi.version()))
            else:
                prims.append(("below", hi.next_block()))
        return prims, carry, False
    parsed = [(op, _Partial(rest)) for op, rest in shape[1]]
    for op, p in parsed:
        prims.extend(_comparator(op or "=", p))
        if p.full and p.pre:
            carry.add(p.low())
    exact = len(parsed) == 1 and parsed[0][0] in ("", "=") and parsed[0][1].full
    return prims, carry, exact


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(" \t"):
        raise RangeError("bad-range", "empty range")
    alts = text.split("||")
    if any(not a.strip(" \t") for a in alts):
        raise RangeError("bad-range", "empty alternative")
    shapes = [_shape_alternative(a) for a in alts]
    built = [_build_alternative(s) for s in shapes]
    exact = len(built) == 1 and built[0][2]
    return Range(text, [(prims, carry) for prims, carry, _ in built], exact)
